/* the board's watchdog device: the first of its class */
#define EMB_SOC_WATCHDOG_DEVICE (&emb_dev_iwdg)

/* the board's RTC device: the first of its class */
#define EMB_SOC_RTC_DEVICE (&emb_dev_rtc)

